/** Parse an ISO date as a local date, or fall back to common text date formats. */
export const guessDateFromText = (text: string): Date | undefined => {
    const isoDate = parseISO(text);
    if (isValid(isoDate)) {
        return isoDate;
    }

    // An invalid ISO calendar date must not be normalized by Date (e.g. February 30).
    const isoDatePart = /^\d{4}-\d{2}-\d{2}/.exec(text)?.[0];
    if (isoDatePart && !isValid(parseISO(isoDatePart))) {
        return undefined;
    }

    const date = new Date(text);
    if (!isValid(date)) {
        return undefined;
    }

    // Date also normalizes impossible slash-separated dates, so check their calendar parts.
    const yearFirst = /^(\d{4})\/(\d{1,2})\/(\d{1,2})$/.exec(text);
    const monthFirst = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text);
    const parts = yearFirst || monthFirst;
    if (parts) {
        const [year, month, day] = yearFirst ? [parts[1], parts[2], parts[3]] : [parts[3], parts[1], parts[2]];
        if (
            date.getFullYear() !== Number(year) ||
            date.getMonth() + 1 !== Number(month) ||
            date.getDate() !== Number(day)
        ) {
            return undefined;
        }
    }

    return date;
};
